def rrf(*rankings, k=60):
    score = {}
    for ranking in rankings:
        for rank, doc in enumerate(ranking, start=1):
            score[doc] = score.get(doc, 0) + 1 / (k + rank)
    return sorted(score.items(), key=lambda x: -x[1])

bm25   = ["news-12", "news-07", "news-31"]   # 낱말이 겹치는 순
vector = ["news-31", "news-12", "news-44"]   # 뜻이 가까운 순
for doc, s in rrf(bm25, vector):
    print(doc, round(s, 5))
# news-12 0.03252
# news-31 0.03227
# news-07 0.01613
# news-44 0.01587
